def _parse_arguments():
    parser = argparse.ArgumentParser(description="Traffic Generator with scapy")
    parser.add_argument("-ipver", "--ip_version", help="IP version", required=True)
    parser.add_argument("-m", "--malformed", help="malformed", required=False)
    parser.add_argument("-f", "--frame_size", help="frame_size", required=False)
    parser.add_argument("-p", "--protocol", help="protocol", required=True)
    parser.add_argument("-s", "--src_port", help="source port", required=False)
    parser.add_argument("-d", "--dst_port", help="destination port", required=False)
    # parser.add_argument("-cmd", "--command", help="command to be executed",
    #                     required=False)
    parser.add_argument("-src", "--source", help="source ip", required=False)
    parser.add_argument("-dst", "--destination", help="destination ip", required=False)
    parser.add_argument("-t", "--type", help="type", required=False)
    parser.add_argument("-c", "--code", help="code", required=False)
    parser.add_argument("-v", "--vlan", help="vlan", required=False)
    parser.add_argument("-b", "--bts_id", help="bts id", required=True)
    parser.add_argument("-intrfc", "--interface", help="interface", required=True)
    parser.add_argument("-sp", "--speed", help="speed", required=False)
    parser.add_argument("-dur", "--duration", help="duration", required=False)
    parser.add_argument("-pkt_count", "--pkt_count", help="packets_count", required=False)
    parser.add_argument("-pad_str", "--pad_str", help="padding value in the pkt", required=False, default='')
    parser.add_argument("-dhcp_options", "--dhcp_opts", help="different dhcp options", required=False)
    argument = parser.parse_args()
    return argument.ip_version, argument.malformed, argument.frame_size, argument.protocol, argument.src_port, \
           argument.dst_port, argument.command, argument.source, argument.destination, argument.type, argument.code, \
           argument.vlan, argument.bts_id, argument.interface, argument.speed, argument.duration, argument.pkt_count, \
           argument.pad_str, argument.dhcp_options


def _generate_pad_string():
    pad1 = bts_id[:4]
    pad2 = datetime.now().strftime('%M%S')
    pad = str(int(pad1) + int(pad2))[:4]
    pad += 'a' * (4 - len(pad))
    print('pad string: {}'.format(pad))
    return pad


def _bind_interface(socket_connect):
    if vlan:
        interface = '{}.{}'.format(interface.split(".")[0], vlan)
        socket_connect.bind(('{}'.format(interface), 0))


def _build_socket_bw_scapy_pc_and_dest():
    s = socket.socket(socket.AF_PACKET, socket.SOCK_RAW)
    s.bind(('{}'.format(interface), 0))
    return s


def _build_protocol_commands_from_profile(pad):
    print("building protocols from profile...")
    packet = None
    # cmd = command
    # if cmd is not None and cmd != '':
    #     ## To be changed from string format to class format
    #     pe = {cmd}
    if get_packet_from_user is not None:
        packet = get_packet_from_user() / '{}'.format(pad)
    else:
        if ip_version.lower() == 'ipv4':
            packet = _build_ipv4_command()
        elif ip_version.lower() == 'ipv6':
            packet = _build_ipv6_command()
    return packet


def _build_ipv6_command():
    print("Building ipv6 command...")
    malformed_pad = ''
    if malformed:
        if frame_size:
            malformed_pad = '/' + 'a' * (int() - 30 - len(pad))
            malformed_pad += pad
    protocol = protocol.lower()
    if protocol == 'icmp':
        packet = Ether() / IPv6(dst='{}'.format(destination)) / ICMPv6ND_RA(type='{}'.format(type),
                                                                            code='{}'.format(code)) / '{}'.format(pad)
    elif protocol == 'sctp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination),
                                nh=132) / SCTP(sport='{}'.format(src_port),
                                               dport='{}'.format(dst_port)) / SCTPChunkInit() / '{}'.format(pad)
    elif protocol == 'gtp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport='{}'.format(src_port), dport='{}'.format(dst_port)) \
                 / GTP_U_Header(TEID=0x31) / IP() / UDP() / '{}'.format(pad)
    elif protocol == 'udp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport={src_port}, dport={dst_port}) / "/'{}'".format(pad)
    elif protocol == 'ntp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=123, dport=123) / "/'{}'".format(pad)
    elif protocol == 'bfd':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=3784, dport=3784) / "/'{}'".format(pad)
    elif protocol == 'isakmp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=500, dport=500) / "/'{}'".format(pad)
    elif protocol == 'ssh':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=49666, dport=22) / "/'{}'".format(pad)
    elif protocol == 'http':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=47096, dport=80) / "/'{}'".format(pad)
    elif protocol == 'https':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=47096, dport=443) / "/'{}'".format(pad)
    elif protocol == 'ptp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=320, dport=320) / "/'{}'".format(pad)
    # elif protocol == 'dhcp':
    #     packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) \
    #              / UDP(sport=68, dport=67) / BOOTP() \
    #              / DHCP(options=[('message-type', 'decline'), 'end']) / '{}'.format(pad)
    elif protocol == 'dhcp':
        packet = Ether() / IPv6(src='{}'.format(source), dst='{}'.format(destination)) / UDP(sport=68, dport=67) / BOOTP() / DHCP(options=[dhcp_options, 'end']) / '{}'.format(pad)
    else:
        raise Exception('Unsupported protocol: {}'.format(protocol))
    return packet


def _build_ipv4_command():
    print("building ipv4 packet....")
    if malformed:
        if frame_size:
            packet = _build_ipv4_packets_for_frame_size()
        elif src_port or dst_port:
            packet = _build_ipv4_packets_for_src_dst_port_option()
    else:
        packet = _build_ipv4_complete_detailed_packet()
    # print "Scapy command for pkt: {}".format(packet)
    return packet


def _build_ipv4_packets_for_frame_size():
    if frame_size:
        frame_pad = 'a' * (int(frame_size) - 30 - len(pad))
        frame_pad += pad
        packet = Ether() / IP(src=source, dst=destination) / SCTP() / '{}'.format(frame_pad) / SCTPChunkInit()
        return packet


def _build_ipv4_packets_for_src_dst_port_option():
    if protocol.lower() == 'sctp':
        packet = Ether() / IP(src=source, dst=destination) / SCTP(
            sport=src_port, dport=dst_port) / SCTPChunkInit() / '{}'.format(pad)
        return packet
    else:
        packet = Ether() / IP(src=source, dst=destination) / UDP(
            sport=src_port, dport=dst_port) / '{}'.format(pad)
        return packet


def _build_ipv4_complete_detailed_packet():
    if protocol == 'sctp':
        packet = Ether() / IP(src='{}'.format(source),
                              dst='{}'.format(destination)) / SCTP() / SCTPChunkInit() / '{}'.format(pad)
    elif protocol is 'udp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) / UDP() / '{}'.format(pad)
    elif protocol == 'ntp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=123, dport=123) / '{}'.format(pad)
    elif protocol == 'bfd':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=3784, dport=3784) / '{}'.format(pad)
    elif protocol == 'icmp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / ICMP() / '{}'.format(pad)
    elif protocol == 'isakmp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=500, dport=500) / '{}'.format(pad)
    elif protocol == 'gtp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=2152, dport=2152) / GTP_U_Header(TEID=0x31) / '{}'.format(pad)
    elif protocol == 'ssh':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=49666, dport=22) / '{}'.format(pad)
    elif protocol == 'http':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=47096, dport=80) / '{}'.format(pad)
    elif protocol == 'https':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / TCP(sport=47096, dport=443) / '{}'.format(pad)
    elif protocol == 'arp':
        packet = Ether(type=0x0806) / ARP(pdst='{}'.format(destination)) / '{}'.format(pad)
    elif protocol == 'ptp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) \
                 / UDP(sport=320, dport=320) / '{}'.format(pad)
    elif protocol == 'twamp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination),
                              len=100, flags=2) / UDP(sport=5004, dport=5018, len=80) / TWAMP() / "/'{}'".format(pad)
    elif protocol == 'dhcp':
        packet = Ether() / IP(src='{}'.format(source), dst='{}'.format(destination)) / UDP(sport=68, dport=67) / BOOTP() / DHCP(options=[dhcp_options, 'end']) / '{}'.format(pad)
    else:
        raise Exception('Unsupported protocol: {}'.format(protocol))
    return packet


def _build_packet(packet):
    built_packet = packet.build()
    packet_len = len(built_packet)
    print('packet length: {}'.format(packet_len))
    return built_packet


def _send_packets(count, time_to_sleep, socket_session, built_packet):
    print("sending {} packets....".format(count))
    iteration = 0
    try:
        while iteration <= count:
            print('packet : {}'.format(iteration))
            response = socket_session.send(built_packet)
            sleep(time_to_sleep)
            iteration += 1
    except Exception as err:
        raise err
    finally:
        print('closing socket')
        socket_session.close()
    # self.session.set_client_configuration(timeout='10 minutes')


def _get_count_value_from_profile():
    if duration is not None:
        count = int(speed) * int(duration)
    elif pkt_count is not None:
        count = int(pkt_count)
    else:
        print("duration/packets not given in profile, using default packets"
              " value 1")
        count = 10
    return count


def get_time_to_sleep_bw_packets():
    time_to_sleep = 1.0 / int(speed)
    print('Time between each packet = {0}'.format(time_to_sleep))
    return time_to_sleep


ip_version, malformed, frame_size, protocol, src_port, dst_port, command, source, destination, type, code, vlan, bts_id, \
interface, speed, duration, pkt_count, pad, dhcp_options = _parse_arguments()
count = _get_count_value_from_profile()
time_to_sleep = get_time_to_sleep_bw_packets()
socket_session = _build_socket_bw_scapy_pc_and_dest()
packet = _build_protocol_commands_from_profile(pad)
_bind_interface(socket_session)
built_packet = _build_packet(packet)
_send_packets(count, time_to_sleep, socket_session, built_packet)